CREATE OR REPLACE FUNCTION public.planning_create_external_invite(_project_id uuid,_name text,_email text,_company text,_type text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; token text; BEGIN
 IF public.planning_external_manager(_project_id) IS NOT TRUE THEN RAISE EXCEPTION 'Du kan ikke invitere til dette prosjektet' USING ERRCODE='42501'; END IF;
 IF _type IS NULL OR _type NOT IN ('customer','supplier') OR _name IS NULL OR length(trim(_name))=0 OR length(trim(_name))>200 OR _company IS NULL OR length(_company)>200 OR _email IS NULL OR length(_email)>254 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Kontroller navn, e-post og type'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_project_id::text,0));
 IF (SELECT count(*) FROM public.planning_activity WHERE planning_project_id=_project_id AND action='external_invited' AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'For mange invitasjoner. Prøv senere'; END IF;
 token:=encode(extensions.gen_random_bytes(32),'hex');
 INSERT INTO public.planning_external_participants(planning_project_id,name,email,company_name,participant_type,created_by,invite_hash,invite_expires_at) VALUES(_project_id,trim(_name),lower(trim(_email)),trim(_company),_type,auth.uid(),encode(extensions.digest(token,'sha256'),'hex'),now()+interval '48 hours') ON CONFLICT(planning_project_id,email) DO UPDATE SET name=EXCLUDED.name,company_name=EXCLUDED.company_name,participant_type=EXCLUDED.participant_type,created_by=EXCLUDED.created_by,status='pending',invite_hash=EXCLUDED.invite_hash,invite_expires_at=EXCLUDED.invite_expires_at,deleted_at=NULL,deleted_by=NULL,accepted_at=NULL RETURNING * INTO e;
 DELETE FROM public.planning_external_sessions WHERE participant_id=e.id;
 INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by) VALUES(_project_id,'external_invited','Ekstern invitert: '||e.name||' · '||e.company_name,auth.uid());
 RETURN jsonb_build_object('id',e.id,'token',token,'name',e.name,'email',e.email,'participant_type',e.participant_type,'project_name',(SELECT name FROM public.planning_projects WHERE id=_project_id)); END $$;
CREATE OR REPLACE FUNCTION public.planning_send_channel_message(_project_id uuid,_channel text,_body text,_external_ids uuid[],_request_id uuid,_reply_to uuid DEFAULT NULL,_token text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; audience jsonb; recipients jsonb; mid uuid; sender_name text; parent public.planning_messages; BEGIN
 IF _project_id IS NULL OR _request_id IS NULL OR _body IS NULL OR length(trim(_body))=0 OR length(_body)>20000 OR _channel IS NULL OR _channel NOT IN ('internal','customer','supplier','all') OR _external_ids IS NULL THEN RAISE EXCEPTION 'Kontroller meldingen og velg mottakere'; END IF;
 IF _token IS NOT NULL THEN e:=public.planning_external_identity(_token); IF e.id IS NULL OR e.planning_project_id IS DISTINCT FROM _project_id OR public.planning_channel_matches(e.participant_type,_channel) IS NOT TRUE THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF; sender_name:=e.name;
 ELSE IF public.has_planning_project_access(_project_id) IS NOT TRUE THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF; SELECT coalesce(pe.full_name,t.name,'MCS') INTO sender_name FROM (SELECT auth.uid() id) u LEFT JOIN public.user_accounts ua ON ua.auth_user_id=u.id AND ua.is_active=true LEFT JOIN public.people pe ON pe.id=ua.person_id LEFT JOIN public.technicians t ON t.user_id=u.id LIMIT 1; END IF;
 audience:=public.planning_channel_people(_project_id,_channel);
 IF EXISTS(SELECT 1 FROM unnest(_external_ids) i WHERE i IS NULL OR NOT audience @> jsonb_build_array(jsonb_build_object('id',i,'kind','external'))) THEN RAISE EXCEPTION 'Mottaker tilhører ikke samtalen' USING ERRCODE='42501'; END IF;
 IF _reply_to IS NOT NULL THEN SELECT * INTO parent FROM public.planning_messages WHERE id=_reply_to AND planning_project_id=_project_id AND channel=_channel AND deleted_at IS NULL; IF parent.id IS NULL OR (e.id IS NOT NULL AND parent.external_author_id IS DISTINCT FROM e.id AND NOT parent.recipient_snapshot @> jsonb_build_array(jsonb_build_object('id',e.id,'kind','external'))) THEN RAISE EXCEPTION 'Ingen tilgang til meldingen du svarer på' USING ERRCODE='42501'; END IF; END IF;
 SELECT coalesce(jsonb_agg(a),'[]'::jsonb) INTO recipients FROM jsonb_array_elements(audience) a WHERE a->>'kind'='internal' OR (a->>'id')::uuid=ANY(_external_ids);
 SELECT id INTO mid FROM public.planning_messages WHERE client_request_id=_request_id AND planning_project_id=_project_id AND channel=_channel AND ((e.id IS NOT NULL AND external_author_id=e.id) OR (e.id IS NULL AND author_id=auth.uid())); IF mid IS NOT NULL THEN RETURN mid; END IF;
 INSERT INTO public.planning_messages(planning_project_id,channel,body,author_id,external_author_id,author_name,recipient_snapshot,client_request_id,reply_to_id) VALUES(_project_id,_channel,trim(_body),CASE WHEN e.id IS NULL THEN auth.uid() END,e.id,sender_name,recipients,_request_id,_reply_to) RETURNING id INTO mid; RETURN mid; END $$;
CREATE OR REPLACE FUNCTION public.planning_set_external_sharing(_project_id uuid,_kind text,_id uuid,_visibility text,_assignee uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF public.planning_external_manager(_project_id) IS NOT TRUE OR _visibility IS NULL OR _visibility NOT IN ('internal','customer','supplier','all') THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF;
 IF _assignee IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.planning_external_participants WHERE id=_assignee AND planning_project_id=_project_id AND status='active' AND deleted_at IS NULL AND public.planning_channel_matches(participant_type,_visibility)) THEN RAISE EXCEPTION 'Del oppgaven med ansvarlig sin gruppe først'; END IF;
 IF _kind='file' THEN UPDATE public.planning_files SET shared_visibility=_visibility WHERE id=_id AND planning_project_id=_project_id AND (_visibility='internal' OR (storage_bucket='planning-files' AND split_part(storage_path,'/',1)=_project_id::text));
 ELSIF _kind='task' THEN UPDATE public.planning_tasks SET shared_visibility=_visibility,external_assignee_id=_assignee WHERE id=_id AND planning_project_id=_project_id;
 ELSIF _kind='work_package' THEN UPDATE public.planning_work_packages SET shared_visibility=_visibility WHERE id=_id AND planning_project_id=_project_id;
 ELSE RAISE EXCEPTION 'Ukjent deling'; END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'Kan ikke dele denne posten. Eldre offentlige filer må lastes opp privat først' USING ERRCODE='42501'; END IF;
 INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by,metadata) VALUES(_project_id,'external_sharing_changed','Ekstern synlighet endret',auth.uid(),jsonb_build_object('kind',_kind,'id',_id,'visibility',_visibility,'assignee',_assignee)); END $$;
CREATE OR REPLACE FUNCTION public.planning_external_complete_task(_token text,_task_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.planning_external_participants; BEGIN e:=public.planning_external_identity(_token); IF e.id IS NULL THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF;
 UPDATE public.planning_tasks SET status='done',completed_at=now() WHERE id=_task_id AND planning_project_id=e.planning_project_id AND external_assignee_id=e.id AND public.planning_channel_matches(e.participant_type,shared_visibility) AND status<>'done'; IF NOT FOUND THEN RAISE EXCEPTION 'Oppgaven er ikke tildelt deg eller er allerede fullført' USING ERRCODE='42501'; END IF; END $$;
COMMENT ON FUNCTION public.planning_send_channel_message(uuid,text,text,uuid[],uuid,uuid,text) IS 'Explicit recipient list required for internal and external senders. NULL never means all.';